const KEY='noda-language';
const norm=v=>String(v||'').replace(/\s+/g,' ').trim();
function t(v){
 const k=norm(v); if(!k)return v;
 if(Object.prototype.hasOwnProperty.call(FR,k))return FR[k];
 let r=k;
 FALLBACK.forEach(([a,b])=>{r=r.replace(new RegExp('\\b'+a.replace(/[.*+?^${}()|[\\]\\]/g,'\\\\$&')+'\\b','gi'),b);});
 return r;
}
function attrs(el,lang){
 ['placeholder','title','aria-label'].forEach(a=>{
  const key='i18n'+a[0].toUpperCase()+a.slice(1), src=el.dataset[key];
  if(!src)return;
  if(!el.dataset['original'+a[0].toUpperCase()+a.slice(1)])el.dataset['original'+a[0].toUpperCase()+a.slice(1)]=el.getAttribute(a)||'';
  el.setAttribute(a,lang==='fr'?t(src):el.dataset['original'+a[0].toUpperCase()+a.slice(1)]);
 });
}
function translateNode(el){
 if(!el.dataset.i18nOriginalHtml)el.dataset.i18nOriginalHtml=el.innerHTML;
 el.innerHTML=t(el.dataset.i18n);
}
function apply(lang){
 lang=lang==='fr'?'fr':'en'; document.documentElement.lang=lang; window.NODA_LANGUAGE=lang;
 document.querySelectorAll('[data-i18n]').forEach(el=>{
  if(!el.dataset.i18nOriginalHtml)el.dataset.i18nOriginalHtml=el.innerHTML;
  el.innerHTML=lang==='fr'?t(el.dataset.i18n):el.dataset.i18nOriginalHtml;
 });
 document.querySelectorAll('[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]').forEach(el=>attrs(el,lang));
 document.querySelectorAll('[data-i18n-toggle]').forEach(b=>{b.textContent=lang==='fr'?'EN':'FR';b.setAttribute('aria-label',lang==='fr'?'Passer en anglais':'Passer en français');b.title=lang==='fr'?'Passer en anglais':'Passer en français';});
 localStorage.setItem(KEY,lang);

if (typeof window.refreshHeroTranslations === 'function') {
  window.refreshHeroTranslations();
}

if (typeof window.refreshChatTranslations === 'function') {
  window.refreshChatTranslations();
}
}
function init(){
 document.querySelectorAll('[data-i18n]').forEach(el=>el.dataset.i18nOriginalHtml ||= el.innerHTML);
 document.querySelectorAll('[data-i18n-toggle]').forEach(b=>b.addEventListener('click',()=>apply(window.NODA_LANGUAGE==='fr'?'en':'fr')));
 apply(localStorage.getItem(KEY)||'en');
 const mo=new MutationObserver(ms=>{
   if(window.NODA_LANGUAGE!=='fr') return;
   ms.forEach(m=>m.addedNodes.forEach(n=>{
     if(n.nodeType!==1) return;
     if(n.matches?.('[data-i18n]')) translateNode(n);
     n.querySelectorAll?.('[data-i18n]').forEach(translateNode);
     if(n.matches?.('[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]')) attrs(n,'fr');
     n.querySelectorAll?.('[data-i18n-placeholder],[data-i18n-title],[data-i18n-aria-label]').forEach(el=>attrs(el,'fr'));
   }));
 });
 mo.observe(document.body,{childList:true,subtree:true});
 mo.observe(document.body,{childList:true,subtree:true});
}
window.NODA_TRANSLATE=apply; window.t=t;
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',init):init();
